1	package agentsetup
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"os"
8		"path/filepath"
9		"strings"
10	)
11	
12	const activationPrefix = "<!-- entire-agent-activation: "
13	const activationSuffix = " -->"
14	
15	type activationRecord struct {
16		SchemaVersion int      `json:"schema_version"`
17		Enabled       []string `json:"enabled"`
18		Mode          Mode     `json:"mode,omitempty"`
19	}
20	
21	type activationState struct {
22		products map[string]bool
23		mode     Mode
24	}
25	
26	func renderActivation(active map[string]bool, mode Mode) string {
27		enabled := []string{}
28		for _, product := range []string{"graph", "brain"} {
29			if active[product] {
30				enabled = append(enabled, product)
31			}
32		}
33		// Omit normal mode to retain byte-for-byte compatibility with existing guides.
34		storedMode := mode
35		if storedMode == ModeNormal {
36			storedMode = ""
37		}
38		record, _ := json.Marshal(activationRecord{SchemaVersion: 1, Enabled: enabled, Mode: storedMode})
39		return guideFor(active, mode) + "\n" + activationPrefix + string(record) + activationSuffix + "\n"
40	}
41	
42	func parseActivation(content string) (activationState, bool, error) {
43		const marker = "<!-- entire-agent-activation:"
44		if !strings.Contains(content, marker) {
45			return activationState{}, false, nil
46		}
47		invalid := func() (activationState, bool, error) {
48			return activationState{}, true, fmt.Errorf("invalid or unsupported agent activation metadata; repair before regenerating")
49		}
50		if strings.Count(content, marker) != 1 {
51			return invalid()
52		}
53		var payload string
54		for _, line := range strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n") {
55			if strings.HasPrefix(line, activationPrefix) && strings.HasSuffix(line, activationSuffix) {
56				payload = strings.TrimSuffix(strings.TrimPrefix(line, activationPrefix), activationSuffix)
57			}
58		}
59		if payload == "" {
60			return invalid()
61		}
62		decoder := json.NewDecoder(strings.NewReader(payload))
63		decoder.DisallowUnknownFields()
64		var record activationRecord
65		if err := decoder.Decode(&record); err != nil {
66			return invalid()
67		}
68		var extra any
69		if err := decoder.Decode(&extra); err != io.EOF {
70			return invalid()
71		}
72		if record.SchemaVersion != 1 || len(record.Enabled) == 0 ||
73			(record.Mode != "" && record.Mode != ModeNormal && record.Mode != ModeStrict) {
74			return invalid()
75		}
76		active := map[string]bool{}
77		for _, product := range record.Enabled {
78			if (product != "graph" && product != "brain") || active[product] {
79				return invalid()
80			}
81			active[product] = true
82		}
83		return activationState{products: active, mode: record.Mode}, true, nil
84	}
85	
86	// Metadata is authoritative once present. Before migration, preserve products
87	// represented by recognized generated guides and legacy managed blocks. A
88	// historical combined guide cannot reveal whether both activations were explicit.
89	func readActivation(repo string) (activationState, error) {
90		root, err := os.OpenRoot(repo)
91		if err != nil {
92			return activationState{}, err
93		}
94		defer root.Close()
95		read := func(name string) (string, bool, error) {
96			info, err := inspectInstructionFile(root, name, filepath.Join(repo, name))
97			if err != nil {
98				return "", false, err
99			}
100			if info == nil {
101				return "", false, nil
102			}
103			data, err := readContainedFile(root, name, maxManagedLandingBytes)
104			return strings.ReplaceAll(string(data), "\r\n", "\n"), true, err
105		}
106		content, present, err := read(Path)
107		if err != nil {
108			return activationState{}, err
109		}
110		if present {
111			active, found, err := parseActivation(content)
112			if err != nil || found {
113				return active, err
114			}
115		}
116		active := map[string]bool{}
117		recognize := func(text string) bool {
118			heading, _, _ := strings.Cut(text, "\n")
119			switch heading {
120			case "# Entire repository agent guide — Graph and Brain":
121				active["graph"], active["brain"] = true, true
122			case "# Entire repository agent guide — Graph", "# entire-graph — instructions for coding agents (follow directly)":
123				active["graph"] = true
124			case "# Entire repository agent guide — Brain", "# Entire Brain coding-agent guide":
125				active["brain"] = true
126			default:
127				return false
128			}
129			return true
130		}
131		if present && !recognize(content) {
132			return activationState{}, fmt.Errorf("unrecognized agent guide %s; preserve or migrate its content before regenerating", Path)
133		}
134		for _, name := range []string{".entire/graph-agent.md", ".entire/brain-agent.md", "AGENTS.md", "CLAUDE.md"} {
135			text, exists, err := read(name)
136			if err != nil {
137				return activationState{}, err
138			}
139			if !exists {
140				continue
141			}
142			if name == "AGENTS.md" || name == "CLAUDE.md" {
143				if _, err := migrateMarkers([]byte(text)); err != nil {
144					return activationState{}, err
145				}
146				for _, product := range []string{"graph", "brain"} {
147					if strings.Contains(text, "<!-- entire-"+product+":begin -->") {
148						active[product] = true
149					}
150				}
151			} else if text != legacyRedirect && !recognize(text) {
152				return activationState{}, fmt.Errorf("unrecognized legacy agent guide %s; preserve or migrate its content before regenerating", name)
153			}
154		}
155		return activationState{products: active}, nil
156	}
