3	import (
4		"bytes"
5		"fmt"
6		"os"
7		"path/filepath"
8		"regexp"
9		"strings"
10	)
11	
12	// Existing names remain redirects for clients with explicit legacy imports.
13	// There is exactly one workflow body, in Path; generated files are not setup state.
14	const legacyRedirect = "Read the repository-root .entire/agent-guide.md for the current agent workflow.\n"
15	
16	func migrateMarkers(content []byte) ([]byte, error) {
17		for _, product := range []string{"graph", "brain"} {
18			begin, end := []byte("<!-- entire-"+product+":begin -->"), []byte("<!-- entire-"+product+":end -->")
19			n, m := bytes.Count(content, begin), bytes.Count(content, end)
20			if n == 0 && m == 0 {
21				continue
22			}
23			a, b := bytes.Index(content, begin), bytes.Index(content, end)
24			if n != 1 || m != 1 || a >= b {
25				return nil, fmt.Errorf("malformed Entire %s managed markers; repair before regenerating", product)
26			}
27			content = append(append([]byte{}, content[:a]...), content[b+len(end):]...)
28		}
29		return content, nil
30	}
31	
32	func preflightLegacy(root *os.Root, abs string) ([]string, error) {
33		var names []string
34		for _, name := range []string{".entire/graph-agent.md", ".entire/brain-agent.md"} {
35			if err := ensureContainedInRepo(root, name, filepath.Join(abs, name), false, ".entire"); err != nil {
36				return nil, err
37			}
38			info, err := statContainedFile(root, name)
39			if os.IsNotExist(err) {
40				continue
41			}
42			if err != nil {
43				return nil, err
44			}
45			if !info.Mode().IsRegular() {
46				return nil, fmt.Errorf("%s is not a regular guide", name)
47			}
48			if err := ensureNoSharedInode(root, name); err != nil {
49				return nil, err
50			}
51			for _, other := range []string{"AGENTS.md", "CLAUDE.md"} {
52				target, err := statContainedFile(root, other)
53				if err == nil && os.SameFile(info, target) {
54					return nil, fmt.Errorf("legacy guide %s aliases instruction file %s", name, other)
55				}
56			}
57			// The canonical guide may already be the target of a legacy symlink.
58			target, err := statContainedFile(root, Path)
59			if err == nil && os.SameFile(info, target) {
60				continue
61			}
62			resolved, err := resolveContainedName(root, name)
63			if err != nil {
64				return nil, err
65			}
66			canonical, err := resolveContainedName(root, Path)
67			if err != nil {
68				return nil, err
69			}
70			if sameResolvedName(resolved, canonical) {
71				continue
72			}
73			names = append(names, name)
74		}
75		return names, nil
76	}
77	func writeLegacy(root *os.Root, names []string) error {
78		for _, name := range names {
79			// Recheck identity after materializing the canonical guide and before writes.
80			a, ea := statContainedFile(root, name)
81			b, eb := statContainedFile(root, Path)
82			if ea == nil && eb == nil && os.SameFile(a, b) {
83				continue
84			}
85			if err := writeContainedFile(root, name, []byte(legacyRedirect), 0644); err != nil {
86				return err
87			}
88		}
89		return nil
90	}
