92	// Context gives explicit roots precedence over the host root; otherwise it finds
93	// the nearest Git root without invoking Git. Explicit roots can be non-Git projects.
94	func Context(explicit, host string) (string, error) {
95		p := explicit
96		if p == "" {
97			p = host
98		}
99		if p != "" {
100			abs, err := filepath.Abs(p)
101			if err != nil {
102				return "", err
103			}
104			info, err := os.Stat(abs)
105			if err != nil {
106				return "", err
107			}
108			if !info.IsDir() {
109				return "", fmt.Errorf("project root is not a directory: %s", abs)
110			}
111			return abs, nil
112		}
113		p, err := os.Getwd()
114		if err != nil {
115			return "", err
116		}
117		for {
118			_, err := os.Lstat(filepath.Join(p, ".git"))
119			if err == nil {
120				return p, nil
121			}
122			if !os.IsNotExist(err) {
123				return "", err
124			}
125			parent := filepath.Dir(p)
126			if parent == p {
127				return "", nil
128			}
129			p = parent
130		}
131	}
132	
133	// safeKey permits only Brain's normalized repository-key components.
134	func safeKey(key string) bool {
135		if key == "" || strings.Contains(key, "\\") {
136			return false
137		}
138		parts := strings.Split(key, "/")
139		if parts[0] == "workspaces" {
140			return false
141		}
142		for _, p := range parts {
143			if p == "" || p == "." || p == ".." || cleanComponent(p) != p {
144				return false
145			}
146		}
147		return true
148	}
149	
150	var unsafeComponent = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)
151	
152	func cleanComponent(s string) string {
153		return strings.Trim(unsafeComponent.ReplaceAllString(s, "-"), "-._")
154	}
